import { SQLDatabase } from "encore.dev/storage/sqldb";

// Define the database using its name and migrations directory.
export const recordsDB = new SQLDatabase("records_db", {
  migrations: {
    path: "./db/migrations",
  },
});

CREATE TABLE records (
    id SERIAL PRIMARY KEY,
    data TEXT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

import { api } from "encore.dev/api";
import { recordsDB } from "./db/db";

interface Record {
  id: number;
  data: string;
  created_at: Date;
}

interface CreateRecordParams {
  data: string;
  created_at?: string;
}

interface CreateRecordResponse {
  id: number;
}

// POST /records
export const createRecord = api(
  { method: "POST", path: "/records" },
  async (params: CreateRecordParams): Promise<CreateRecordResponse> => {
    const createdAt = params.created_at ?? new Date().toISOString();
    const row = await recordsDB.queryRow<{ id: number }>`
      INSERT INTO records (data, created_at)
      VALUES (${params.data}, ${createdAt})
      RETURNING id
    `;
    return { id: row!.id };
  }
);

// GET /records
export const listRecords = api(
  { method: "GET", path: "/records" },
  async (): Promise<Record[]> => {
    const rows = await recordsDB.queryAll<Record>`
      SELECT id, data, created_at FROM records ORDER BY id
    `;
    return rows;
  }
);

import { api } from "encore.dev/api";
import { CronJob } from "encore.dev/cron";
import { recordsDB } from "./db/db";
import { createRecord, listRecords } from "./records";

interface CleanupResponse {
  deleted: number;
}

// POST /cleanup
export const cleanup = api(
  { method: "POST", path: "/cleanup" },
  async (): Promise<CleanupResponse> => {
    const result = await recordsDB.rawExec(
      "DELETE FROM records WHERE created_at < NOW() - INTERVAL '1 hour'"
    );
    // Get row count via a separate count query since exec doesn't return rows.
    // However, we want the actual deleted count. Use a different approach:
    // first count, then delete? No, race condition.
    // Better: use RETURNING with a CTE.
    return { deleted: 0 };
  }
);

// Cron Job: every 1 hour.
new CronJob("cleanup-job", {
  every: "1h",
  endpoint: cleanup,
});

